def district_article(d, notes):
    return dict(slug=f"plesen-{d['slug']}", img=None, h1=f"Плесень {d['loc']}: где искать и как бороться",
                desc=f"Почему {d['loc']} появляется плесень, типичные места и что делать владельцу или арендатору.",
                short=f"{d['intro']} {notes['walls']}",
                sections=[("Почему здесь сыро", d["intro"]), ("Стены и потолки", notes["walls"]), ("Ванные", notes["bath"]),
                          ("Дерево и мебель", notes["wood"]), ("Типичные риски района", "; ".join(d["risks"]).capitalize() + "."),
                          ("Что делать", "Найти источник влаги, обработать очаги, просушить, защитить покрытием и наладить вентиляцию. Наружные работы — в сухой сезон.")])
